"""User-facing recovery advice selected by floppy-operation error helpers."""

_LANGUAGE_CODES = ("en", "es", "fr", "de", "it", "pt-BR", "bg", "nl", "pl", "ja", "ko", "zh-Hans")


def _translations(*values):
    if len(values) != len(_LANGUAGE_CODES):
        raise ValueError("Floppy guidance must cover every language.")
    return dict(zip(_LANGUAGE_CODES, values))


